const fs = require('fs');
const path = require('path');

const eventsDir = '/data/events';
const files = fs.readdirSync(eventsDir).filter(f => f.endsWith('.json')).sort();

const events = [];

files.forEach(file => {
  const content = fs.readFileSync(path.join(eventsDir, file), 'utf8');
  const event = JSON.parse(content.trim());

  // Convert to ClickHouse format
  const clickhouseEvent = {
    id: event.event_id,
    userId: event.user_id,
    timestamp: event.event_ts.replace('T', ' ').replace('Z', ''),
    eventType: event.event_type,
    productId: event.product_id,
    propertiesPage: event.properties?.page || null,
    propertiesPrice: event.properties?.price || null
  };

  events.push(clickhouseEvent);
});

// Generate INSERT statements
console.log('-- Loading all events');
console.log('TRUNCATE TABLE local_events;');

const batchSize = 10;
for (let i = 0; i < events.length; i += batchSize) {
  const batch = events.slice(i, i + batchSize);

  console.log('INSERT INTO local_events (id, userId, timestamp, eventType, productId, propertiesPage, propertiesPrice) VALUES');

  const values = batch.map(e =>
    `('${e.id}', '${e.userId}', '${e.timestamp}', '${e.eventType}', '${e.productId}', ${e.propertiesPage ? `'${e.propertiesPage}'` : 'NULL'}, ${e.propertiesPrice || 'NULL'})`
  );

  console.log(values.join(',\n') + ';');
  console.log('');
}

console.log('-- Verify data loaded');
console.log('SELECT COUNT(*) as total_events FROM local_events;');
console.log('SELECT eventType, COUNT(*) as count FROM local_events GROUP BY eventType ORDER BY eventType;');

